insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA', 'Deoxyribonucleic acid (; DNA) is a polymer composed of two polynucleotide chains that coil around each other to form a double helix. The polymer carries genetic instructions for the development, functioning, growth and reproduction of all known organisms and many viruses. DNA and ribonucleic acid (RNA) are nucleic acids. Alongside proteins, lipids and complex carbohydrates (polysaccharides), nucleic acids are one of the four major types of macromolecules that are essential for all known forms of life. The two DNA strands are known as polynucleotides as they are composed of simpler monomeric units called nucleotides. Each nucleotide is composed of one of four nitrogen-containing nucleobases (cytosine [C], guanine [G], adenine [A] or thymine [T]), a sugar called deoxyribose, and a phosphate group. The nucleotides are joined to one another in a chain by covalent bonds (known as the phosphodiester linkage) between the sugar of one nucleotide and the phosphate of the next, resulting in an alternating sugar-phosphate backbone. The nitrogenous bases of the two separate polynucleotide strands are bound together, according to base pairing rules (A with T and C with G), with hydrogen bonds to make double-stranded DNA. The complementary nitrogenous bases are divided into two groups, the single-ringed pyrimidines and the double-ringed purines. In DNA, the pyrimidines are thymine and cytosine; the purines are adenine and guanine.', 'Wikipedia: DNA', 'https://en.wikipedia.org/w/index.php?title=DNA&oldid=1379332306', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Deoxyribonucleic acid (; DNA) is a polymer composed of two polynucleotide chains that coil around each other to form a double helix. The polymer carries genetic instructions for the development, functioning, growth and reproduction of all known organisms and many viruses. DNA and ribonucleic acid (RNA) are nucleic acids. Alongside proteins, lipids and complex carbohydrates (polysaccharides), nucleic acids are one of the four major types of macromolecules that are essential for all known forms of life. The two DNA strands are known as polynucleotides as they are composed of simpler monomeric units called nucleotides. Each nucleotide is composed of one of four nitrogen-containing nucleobases (cytosine [C], guanine [G], adenine [A] or thymine [T]), a sugar called deoxyribose, and a phosphate group. The nucleotides are joined to one another in a chain by covalent bonds (known as the phosphodiester linkage) between the sugar of one nucleotide and the phosphate of the next, resulting in an alternating sugar-phosphate backbone. The nitrogenous bases of the two separate polynucleotide strands are bound together, according to base pairing rules (A with T and C with G), with hydrogen bonds to make double-stranded DNA. The complementary nitrogenous bases are divided into two groups, the single-ringed pyrimidines and the double-ringed purines. In DNA, the pyrimidines are thymine and cytosine; the purines are adenine and guanine.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA', 'Both strands of double-stranded DNA store the same biological information. This information is replicated when the two strands separate. The two strands of DNA run in opposite directions to each other and are thus antiparallel. Attached to each sugar is one of four types of nucleobases (or bases). It is the sequence of these four nucleobases along the backbone that encodes genetic information. RNA strands are created using DNA strands as a template in a process called transcription, where DNA bases are exchanged for their corresponding bases except in the case of thymine (T), for which RNA substitutes uracil (U). Under the genetic code, these RNA strands specify the sequence of amino acids within proteins in a process called translation.', 'Wikipedia: DNA', 'https://en.wikipedia.org/w/index.php?title=DNA&oldid=1379332306', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Both strands of double-stranded DNA store the same biological information. This information is replicated when the two strands separate. The two strands of DNA run in opposite directions to each other and are thus antiparallel. Attached to each sugar is one of four types of nucleobases (or bases). It is the sequence of these four nucleobases along the backbone that encodes genetic information. RNA strands are created using DNA strands as a template in a process called transcription, where DNA bases are exchanged for their corresponding bases except in the case of thymine (T), for which RNA substitutes uracil (U). Under the genetic code, these RNA strands specify the sequence of amino acids within proteins in a process called translation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA', 'Within eukaryotic cells, DNA is organized into long structures called chromosomes. Before typical cell division, these chromosomes are duplicated in the process of DNA replication, providing a complete set of chromosomes for each daughter cell. Eukaryotic organisms (animals, plants, fungi and protists) store most of their DNA inside the cell nucleus as nuclear DNA, and some in the mitochondria as mitochondrial DNA or in chloroplasts as chloroplast DNA. In contrast, prokaryotes (bacteria and archaea) store their DNA only in the cytoplasm, in circular chromosomes. Within eukaryotic chromosomes, chromatin proteins, such as histones, compact and organize DNA. These compacting structures guide the interactions between DNA and other proteins, helping control which parts of the DNA are transcribed.', 'Wikipedia: DNA', 'https://en.wikipedia.org/w/index.php?title=DNA&oldid=1379332306', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Within eukaryotic cells, DNA is organized into long structures called chromosomes. Before typical cell division, these chromosomes are duplicated in the process of DNA replication, providing a complete set of chromosomes for each daughter cell. Eukaryotic organisms (animals, plants, fungi and protists) store most of their DNA inside the cell nucleus as nuclear DNA, and some in the mitochondria as mitochondrial DNA or in chloroplasts as chloroplast DNA. In contrast, prokaryotes (bacteria and archaea) store their DNA only in the cytoplasm, in circular chromosomes. Within eukaryotic chromosomes, chromatin proteins, such as histones, compact and organize DNA. These compacting structures guide the interactions between DNA and other proteins, helping control which parts of the DNA are transcribed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA: Properties', 'DNA does not usually exist as a single strand, but instead as a pair of strands that are held tightly together. These two long strands coil around each other, in the shape of a double helix. The nucleotide contains both a segment of the backbone of the molecule (which holds the chain together) and a nucleobase (which interacts with the other DNA strand in the helix). A nucleobase linked to a sugar is called a nucleoside, and a base linked to a sugar and to one or more phosphate groups is called a nucleotide. A biopolymer comprising multiple linked nucleotides (as in DNA) is called a polynucleotide.', 'Wikipedia: DNA', 'https://en.wikipedia.org/w/index.php?title=DNA&oldid=1379332306', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'DNA does not usually exist as a single strand, but instead as a pair of strands that are held tightly together. These two long strands coil around each other, in the shape of a double helix. The nucleotide contains both a segment of the backbone of the molecule (which holds the chain together) and a nucleobase (which interacts with the other DNA strand in the helix). A nucleobase linked to a sugar is called a nucleoside, and a base linked to a sugar and to one or more phosphate groups is called a nucleotide. A biopolymer comprising multiple linked nucleotides (as in DNA) is called a polynucleotide.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA: Properties', 'The structure of DNA is dynamic along its length, being capable of coiling into tight loops and other shapes. In all species it is composed of two helical chains, bound to each other by hydrogen bonds. The two chains are coiled around the same axis (but not directly opposite one to the other), and have the same pitch of 34 ångströms (3.4 nm). Ignoring the identities of the bases, the line group is D1(q), where q stands for the turn per base pair, which is around a tenth of a full turn. In the usual form (B-DNA), the twist is right-handed, like a normal screw that advances when turned clockwise. The pair of chains have a radius of 10 Å (1.0 nm). According to another study, when measured in a different solution, the DNA chain measured 22–26 Å (2.2–2.6 nm) wide, and one nucleotide unit measured 3.3 Å (0.33 nm) long. The buoyant density of most DNA is 1.7g/cm3.', 'Wikipedia: DNA', 'https://en.wikipedia.org/w/index.php?title=DNA&oldid=1379332306', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The structure of DNA is dynamic along its length, being capable of coiling into tight loops and other shapes. In all species it is composed of two helical chains, bound to each other by hydrogen bonds. The two chains are coiled around the same axis (but not directly opposite one to the other), and have the same pitch of 34 ångströms (3.4 nm). Ignoring the identities of the bases, the line group is D1(q), where q stands for the turn per base pair, which is around a tenth of a full turn. In the usual form (B-DNA), the twist is right-handed, like a normal screw that advances when turned clockwise. The pair of chains have a radius of 10 Å (1.0 nm). According to another study, when measured in a different solution, the DNA chain measured 22–26 Å (2.2–2.6 nm) wide, and one nucleotide unit measured 3.3 Å (0.33 nm) long. The buoyant density of most DNA is 1.7g/cm3.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA: Properties', 'The backbone of the DNA strand is made from alternating phosphate and sugar groups. The sugar in DNA is 2-deoxyribose, which is a pentose (five-carbon) sugar. The sugars are joined by phosphate groups that form phosphodiester bonds between the third and fifth carbon atoms of adjacent sugar rings. These are known as the 3′-end (three prime end), and 5′-end (five prime end) carbons, the prime symbol being used to distinguish these carbon atoms from those of the base to which the deoxyribose forms a glycosidic bond.', 'Wikipedia: DNA', 'https://en.wikipedia.org/w/index.php?title=DNA&oldid=1379332306', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The backbone of the DNA strand is made from alternating phosphate and sugar groups. The sugar in DNA is 2-deoxyribose, which is a pentose (five-carbon) sugar. The sugars are joined by phosphate groups that form phosphodiester bonds between the third and fifth carbon atoms of adjacent sugar rings. These are known as the 3′-end (three prime end), and 5′-end (five prime end) carbons, the prime symbol being used to distinguish these carbon atoms from those of the base to which the deoxyribose forms a glycosidic bond.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA: Properties', 'Therefore, any DNA strand normally has one end at which there is a phosphate group attached to the 5′ carbon of a ribose (the 5′ phosphoryl) and another end at which there is a free hydroxyl group attached to the 3′ carbon of a ribose (the 3′ hydroxyl). The orientation of the 3′ and 5′ carbons along the sugar-phosphate backbone confers directionality (sometimes called polarity) to each DNA strand. In a nucleic acid double helix, the direction of the nucleotides in one strand is opposite to their direction in the other strand: the strands are antiparallel. The asymmetric ends of DNA strands are said to have a directionality of five prime end (5′ ), and three prime end (3′), with the 5′ end having a terminal phosphate group and the 3′ end a terminal hydroxyl group. One major difference between DNA and RNA is the sugar, with the 2-deoxyribose in DNA being replaced by the related pentose sugar ribose in RNA.', 'Wikipedia: DNA', 'https://en.wikipedia.org/w/index.php?title=DNA&oldid=1379332306', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Therefore, any DNA strand normally has one end at which there is a phosphate group attached to the 5′ carbon of a ribose (the 5′ phosphoryl) and another end at which there is a free hydroxyl group attached to the 3′ carbon of a ribose (the 3′ hydroxyl). The orientation of the 3′ and 5′ carbons along the sugar-phosphate backbone confers directionality (sometimes called polarity) to each DNA strand. In a nucleic acid double helix, the direction of the nucleotides in one strand is opposite to their direction in the other strand: the strands are antiparallel. The asymmetric ends of DNA strands are said to have a directionality of five prime end (5′ ), and three prime end (3′), with the 5′ end having a terminal phosphate group and the 3′ end a terminal hydroxyl group. One major difference between DNA and RNA is the sugar, with the 2-deoxyribose in DNA being replaced by the related pentose sugar ribose in RNA.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA: Properties', 'The DNA double helix is stabilized primarily by two forces: hydrogen bonds between nucleotides and base-stacking interactions among aromatic nucleobases. The four bases found in DNA are adenine (A), cytosine (C), guanine (G) and thymine (T). These four bases are attached to the sugar-phosphate to form the complete nucleotide, as shown for adenosine monophosphate. Adenine pairs with thymine and guanine pairs with cytosine, forming A-T and G-C base pairs.', 'Wikipedia: DNA', 'https://en.wikipedia.org/w/index.php?title=DNA&oldid=1379332306', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The DNA double helix is stabilized primarily by two forces: hydrogen bonds between nucleotides and base-stacking interactions among aromatic nucleobases. The four bases found in DNA are adenine (A), cytosine (C), guanine (G) and thymine (T). These four bases are attached to the sugar-phosphate to form the complete nucleotide, as shown for adenosine monophosphate. Adenine pairs with thymine and guanine pairs with cytosine, forming A-T and G-C base pairs.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA replication', 'DNA replication is the process by which a cell makes exact copies of its DNA. This process occurs in all organisms and is essential to biological inheritance, cell division, and repair of damaged tissues. DNA replication ensures that each of the newly divided daughter cells receives its own copy of each DNA molecule. DNA most commonly occurs in double-stranded form, made up of two complementary strands held together by base pairing of the nucleotides comprising each strand. The two linear strands of a double-stranded DNA molecule typically twist together in the shape of a double helix. During replication, the two strands are separated, and each strand of the original DNA molecule then serves as a template for the production of a complementary counterpart strand, a process referred to as semiconservative replication. As a result, each replicated DNA molecule is composed of one original DNA strand as well as one newly synthesized strand. Cellular proofreading and error-checking mechanisms ensure near-perfect fidelity for DNA replication.', 'Wikipedia: DNA replication', 'https://en.wikipedia.org/w/index.php?title=DNA_replication&oldid=1376313272', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'DNA replication is the process by which a cell makes exact copies of its DNA. This process occurs in all organisms and is essential to biological inheritance, cell division, and repair of damaged tissues. DNA replication ensures that each of the newly divided daughter cells receives its own copy of each DNA molecule. DNA most commonly occurs in double-stranded form, made up of two complementary strands held together by base pairing of the nucleotides comprising each strand. The two linear strands of a double-stranded DNA molecule typically twist together in the shape of a double helix. During replication, the two strands are separated, and each strand of the original DNA molecule then serves as a template for the production of a complementary counterpart strand, a process referred to as semiconservative replication. As a result, each replicated DNA molecule is composed of one original DNA strand as well as one newly synthesized strand. Cellular proofreading and error-checking mechanisms ensure near-perfect fidelity for DNA replication.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA replication', 'DNA replication usually begins at specific locations known as origins of replication which are scattered across the genome. Unwinding of DNA at the origin is accommodated by enzymes known as helicases and results in replication forks growing bi-directionally from the origin. Numerous proteins are associated with the replication fork to help in the initiation and continuation of DNA synthesis. Most prominently, DNA polymerase synthesizes the new strands by incorporating nucleotides that complement the nucleotides of the template strand. DNA replication occurs during the S (synthesis) stage of interphase. DNA replication can also be performed in vitro (artificially, outside a cell). DNA polymerases isolated from cells and artificial DNA primers can be used to start DNA synthesis at known sequences in a template DNA molecule. Polymerase chain reaction (PCR), ligase chain reaction (LCR), and transcription-mediated amplification (TMA) are all common examples of this technique. In March 2021, researchers reported evidence suggesting that a preliminary form of transfer RNA, a necessary component of translation (the biological synthesis of new proteins in accordance with the genetic code), could have been a replicator molecule itself in the early abiogenesis of primordial life.', 'Wikipedia: DNA replication', 'https://en.wikipedia.org/w/index.php?title=DNA_replication&oldid=1376313272', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'DNA replication usually begins at specific locations known as origins of replication which are scattered across the genome. Unwinding of DNA at the origin is accommodated by enzymes known as helicases and results in replication forks growing bi-directionally from the origin. Numerous proteins are associated with the replication fork to help in the initiation and continuation of DNA synthesis. Most prominently, DNA polymerase synthesizes the new strands by incorporating nucleotides that complement the nucleotides of the template strand. DNA replication occurs during the S (synthesis) stage of interphase. DNA replication can also be performed in vitro (artificially, outside a cell). DNA polymerases isolated from cells and artificial DNA primers can be used to start DNA synthesis at known sequences in a template DNA molecule. Polymerase chain reaction (PCR), ligase chain reaction (LCR), and transcription-mediated amplification (TMA) are all common examples of this technique. In March 2021, researchers reported evidence suggesting that a preliminary form of transfer RNA, a necessary component of translation (the biological synthesis of new proteins in accordance with the genetic code), could have been a replicator molecule itself in the early abiogenesis of primordial life.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA replication: DNA structure', 'DNA is a double-stranded structure, with both strands coiled together to form the characteristic double helix. Each single strand of DNA is a chain of four types of nucleotides. Nucleotides in DNA contain a deoxyribose sugar, a phosphate, and a nucleobase. The four types of nucleotide correspond to the four nucleobases: adenine, cytosine, guanine, and thymine, commonly abbreviated as A, C, G, and T, respectively. Adenine and guanine are purine nucleobases, while cytosine and thymine are pyrimidines. These nucleotides form phosphodiester bonds, creating phosphate-deoxyribose backbone of the DNA double helix with the nucleobases pointing inward (i.e., toward the opposing strand). Complementary nucleobases are matched between strands through hydrogen bonds to form base pairs. Adenine pairs with thymine (two hydrogen bonds), and guanine pairs with cytosine (three hydrogen bonds).', 'Wikipedia: DNA replication', 'https://en.wikipedia.org/w/index.php?title=DNA_replication&oldid=1376313272', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'DNA is a double-stranded structure, with both strands coiled together to form the characteristic double helix. Each single strand of DNA is a chain of four types of nucleotides. Nucleotides in DNA contain a deoxyribose sugar, a phosphate, and a nucleobase. The four types of nucleotide correspond to the four nucleobases: adenine, cytosine, guanine, and thymine, commonly abbreviated as A, C, G, and T, respectively. Adenine and guanine are purine nucleobases, while cytosine and thymine are pyrimidines. These nucleotides form phosphodiester bonds, creating phosphate-deoxyribose backbone of the DNA double helix with the nucleobases pointing inward (i.e., toward the opposing strand). Complementary nucleobases are matched between strands through hydrogen bonds to form base pairs. Adenine pairs with thymine (two hydrogen bonds), and guanine pairs with cytosine (three hydrogen bonds).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA replication: DNA structure', 'DNA strands have a directionality, and the different ends of a single strand are called the "3′ (three-prime) end" and the "5′ (five-prime) end". By convention, if the base sequence of a single strand of DNA is given, the left end of the sequence is the 5′ end, while the right end of the sequence is the 3′ end. The strands of the double helix are anti-parallel, with one being 5′ to 3′, and the opposite strand 3′ to 5′. These terms refer to the chemical convention of numbering the carbon atoms comprising the deoxyribose molecule and indicate the specific carbon atom to which the next phosphate in the chain attaches. Directionality has consequences in DNA synthesis, because DNA polymerase can synthesize DNA in only one direction by adding nucleotides to the 3′ end of a DNA strand.', 'Wikipedia: DNA replication', 'https://en.wikipedia.org/w/index.php?title=DNA_replication&oldid=1376313272', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'DNA strands have a directionality, and the different ends of a single strand are called the "3′ (three-prime) end" and the "5′ (five-prime) end". By convention, if the base sequence of a single strand of DNA is given, the left end of the sequence is the 5′ end, while the right end of the sequence is the 3′ end. The strands of the double helix are anti-parallel, with one being 5′ to 3′, and the opposite strand 3′ to 5′. These terms refer to the chemical convention of numbering the carbon atoms comprising the deoxyribose molecule and indicate the specific carbon atom to which the next phosphate in the chain attaches. Directionality has consequences in DNA synthesis, because DNA polymerase can synthesize DNA in only one direction by adding nucleotides to the 3′ end of a DNA strand.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA replication: DNA structure', 'The pairing of complementary bases in DNA (through hydrogen bonding) means that the information contained within each strand is redundant. Phosphodiester (intra-strand) bonds are stronger than hydrogen (inter-strand) bonds. The actual job of the phosphodiester bonds is to connect the 5'' carbon atom of one nucleotide to the 3'' carbon atom of another nucleotide, while the hydrogen bonds stabilize DNA double helices across the helix axis but not in the direction of the longitudinal axis. This makes it possible to separate the strands from one another. The nucleotides on a single strand can therefore be used to reconstruct nucleotides on a newly synthesized partner strand.', 'Wikipedia: DNA replication', 'https://en.wikipedia.org/w/index.php?title=DNA_replication&oldid=1376313272', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The pairing of complementary bases in DNA (through hydrogen bonding) means that the information contained within each strand is redundant. Phosphodiester (intra-strand) bonds are stronger than hydrogen (inter-strand) bonds. The actual job of the phosphodiester bonds is to connect the 5'' carbon atom of one nucleotide to the 3'' carbon atom of another nucleotide, while the hydrogen bonds stabilize DNA double helices across the helix axis but not in the direction of the longitudinal axis. This makes it possible to separate the strands from one another. The nucleotides on a single strand can therefore be used to reconstruct nucleotides on a newly synthesized partner strand.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA replication: DNA polymerase', 'DNA polymerases are a family of enzymes that carry out all forms of DNA replication. DNA polymerases in general cannot initiate synthesis of new strands but can only extend an existing DNA or RNA strand paired with a template strand. To begin synthesis, a short fragment of RNA, called a primer, must be created and paired with the template DNA strand.', 'Wikipedia: DNA replication', 'https://en.wikipedia.org/w/index.php?title=DNA_replication&oldid=1376313272', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'DNA polymerases are a family of enzymes that carry out all forms of DNA replication. DNA polymerases in general cannot initiate synthesis of new strands but can only extend an existing DNA or RNA strand paired with a template strand. To begin synthesis, a short fragment of RNA, called a primer, must be created and paired with the template DNA strand.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA replication: DNA polymerase', 'DNA polymerase adds a new strand of DNA by extending the 3′ end of an existing nucleotide chain, adding new nucleotides matched to the template strand, one at a time, via the creation of phosphodiester bonds. The energy for this process of DNA polymerization comes from hydrolysis of the high-energy phosphate (phosphoanhydride) bonds between the three phosphates attached to each unincorporated base. Free bases with an attached sugar molecule (deoxyribose in the case of DNA) are called nucleosides, and nucleosides with one or more attached phosphate groups are called nucleotides; in particular, nucleosides with three attached phosphate groups are called nucleoside triphosphates. When a free nucleotide is being added to a growing DNA strand, the formation of a phosphodiester bond between the proximal phosphate of the free nucleotide and the deoxyribose of another nucleotide within the growing chain is accompanied by hydrolysis of a high-energy phosphate bond with release of the free nucleotide''s two distal phosphate groups as a pyrophosphate. Enzymatic hydrolysis of the resulting pyrophosphate into inorganic phosphate consumes a second high-energy phosphate bond and renders the reaction effectively irreversible.', 'Wikipedia: DNA replication', 'https://en.wikipedia.org/w/index.php?title=DNA_replication&oldid=1376313272', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'DNA polymerase adds a new strand of DNA by extending the 3′ end of an existing nucleotide chain, adding new nucleotides matched to the template strand, one at a time, via the creation of phosphodiester bonds. The energy for this process of DNA polymerization comes from hydrolysis of the high-energy phosphate (phosphoanhydride) bonds between the three phosphates attached to each unincorporated base. Free bases with an attached sugar molecule (deoxyribose in the case of DNA) are called nucleosides, and nucleosides with one or more attached phosphate groups are called nucleotides; in particular, nucleosides with three attached phosphate groups are called nucleoside triphosphates. When a free nucleotide is being added to a growing DNA strand, the formation of a phosphodiester bond between the proximal phosphate of the free nucleotide and the deoxyribose of another nucleotide within the growing chain is accompanied by hydrolysis of a high-energy phosphate bond with release of the free nucleotide''s two distal phosphate groups as a pyrophosphate. Enzymatic hydrolysis of the resulting pyrophosphate into inorganic phosphate consumes a second high-energy phosphate bond and renders the reaction effectively irreversible.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'DNA replication: DNA polymerase', 'In general, DNA polymerases are highly accurate, with an intrinsic error rate of less than one mistake for every 107 nucleotides added. Some DNA polymerases can also delete nucleotides from the end of a developing strand in order to fix mismatched bases. This is known as proofreading. Finally, post-replication mismatch repair mechanisms monitor the DNA for errors, being capable of distinguishing mismatches in the newly synthesized DNA strand from the original strand sequence. Together, these three discrimination steps enable replication fidelity of less than one mistake for every 109 nucleotides added. The rate of DNA replication in a living cell was first measured as the rate of phage T4 DNA elongation in phage-infected E. coli. During the period of exponential DNA increase at 37 °C, the rate was 749 nucleotides per second. The mutation rate per base pair per replication during phage T4 DNA synthesis is 1.7 per 108.', 'Wikipedia: DNA replication', 'https://en.wikipedia.org/w/index.php?title=DNA_replication&oldid=1376313272', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'In general, DNA polymerases are highly accurate, with an intrinsic error rate of less than one mistake for every 107 nucleotides added. Some DNA polymerases can also delete nucleotides from the end of a developing strand in order to fix mismatched bases. This is known as proofreading. Finally, post-replication mismatch repair mechanisms monitor the DNA for errors, being capable of distinguishing mismatches in the newly synthesized DNA strand from the original strand sequence. Together, these three discrimination steps enable replication fidelity of less than one mistake for every 109 nucleotides added. The rate of DNA replication in a living cell was first measured as the rate of phage T4 DNA elongation in phage-infected E. coli. During the period of exponential DNA increase at 37 °C, the rate was 749 nucleotides per second. The mutation rate per base pair per replication during phage T4 DNA synthesis is 1.7 per 108.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Transcription (biology)', 'Transcription is the process of duplicating a segment of DNA into RNA for the purpose of gene expression. Some segments of DNA are transcribed into RNA molecules that can encode proteins, called messenger RNA (mRNA). Other segments of DNA are transcribed into RNA molecules called non-coding RNAs (ncRNAs). Both DNA and RNA are nucleic acids, composed of nucleotide sequences. During transcription, a DNA sequence is read by an RNA polymerase, which produces a complementary RNA strand called a primary transcript. In virology, the term transcription is used when referring to mRNA synthesis from a viral RNA molecule. The genome of many RNA viruses is composed of negative-sense RNA which acts as a template for positive sense viral messenger RNA - a necessary step in the synthesis of viral proteins needed for viral replication. This process is catalyzed by a viral RNA dependent RNA polymerase.', 'Wikipedia: Transcription (biology)', 'https://en.wikipedia.org/w/index.php?title=Transcription_(biology)&oldid=1376993847', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Transcription is the process of duplicating a segment of DNA into RNA for the purpose of gene expression. Some segments of DNA are transcribed into RNA molecules that can encode proteins, called messenger RNA (mRNA). Other segments of DNA are transcribed into RNA molecules called non-coding RNAs (ncRNAs). Both DNA and RNA are nucleic acids, composed of nucleotide sequences. During transcription, a DNA sequence is read by an RNA polymerase, which produces a complementary RNA strand called a primary transcript. In virology, the term transcription is used when referring to mRNA synthesis from a viral RNA molecule. The genome of many RNA viruses is composed of negative-sense RNA which acts as a template for positive sense viral messenger RNA - a necessary step in the synthesis of viral proteins needed for viral replication. This process is catalyzed by a viral RNA dependent RNA polymerase.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Transcription (biology): Background', 'A DNA transcription unit encoding for a protein may contain both a coding sequence, which will be translated into the protein, and regulatory sequences, which direct and regulate the synthesis of that protein. The regulatory sequence before (upstream from) the coding sequence is called the five prime untranslated regions (5''UTR); the sequence after (downstream from) the coding sequence is called the three prime untranslated regions (3''UTR). As opposed to DNA replication, transcription results in an RNA complement that includes the nucleotide uracil (U) in all instances where thymine (T) would have occurred in a DNA complement.', 'Wikipedia: Transcription (biology)', 'https://en.wikipedia.org/w/index.php?title=Transcription_(biology)&oldid=1376993847', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'A DNA transcription unit encoding for a protein may contain both a coding sequence, which will be translated into the protein, and regulatory sequences, which direct and regulate the synthesis of that protein. The regulatory sequence before (upstream from) the coding sequence is called the five prime untranslated regions (5''UTR); the sequence after (downstream from) the coding sequence is called the three prime untranslated regions (3''UTR). As opposed to DNA replication, transcription results in an RNA complement that includes the nucleotide uracil (U) in all instances where thymine (T) would have occurred in a DNA complement.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Transcription (biology): Background', 'Only one of the two DNA strands serves as a template for transcription. The antisense strand of DNA is read by RNA polymerase from the 3'' end to the 5'' end during transcription (3'' → 5''). The complementary RNA is created in the opposite direction, in the 5'' → 3'' direction, matching the sequence of the sense strand except switching uracil for thymine. This directionality is because RNA polymerase can only add nucleotides to the 3'' end of the growing mRNA chain. This use of only the 3'' → 5'' DNA strand eliminates the need for the Okazaki fragments that are seen in DNA replication. This also removes the need for an RNA primer to initiate RNA synthesis, as is the case in DNA replication. The non-template (sense) strand of DNA is called the coding strand, because its sequence is the same as the newly created RNA transcript (except for the substitution of uracil for thymine). This is the strand that is used by convention when presenting a DNA sequence. Transcription has some proofreading mechanisms, but they are fewer and less effective than the controls for copying DNA. As a result, transcription has a lower copying fidelity than DNA replication.', 'Wikipedia: Transcription (biology)', 'https://en.wikipedia.org/w/index.php?title=Transcription_(biology)&oldid=1376993847', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Only one of the two DNA strands serves as a template for transcription. The antisense strand of DNA is read by RNA polymerase from the 3'' end to the 5'' end during transcription (3'' → 5''). The complementary RNA is created in the opposite direction, in the 5'' → 3'' direction, matching the sequence of the sense strand except switching uracil for thymine. This directionality is because RNA polymerase can only add nucleotides to the 3'' end of the growing mRNA chain. This use of only the 3'' → 5'' DNA strand eliminates the need for the Okazaki fragments that are seen in DNA replication. This also removes the need for an RNA primer to initiate RNA synthesis, as is the case in DNA replication. The non-template (sense) strand of DNA is called the coding strand, because its sequence is the same as the newly created RNA transcript (except for the substitution of uracil for thymine). This is the strand that is used by convention when presenting a DNA sequence. Transcription has some proofreading mechanisms, but they are fewer and less effective than the controls for copying DNA. As a result, transcription has a lower copying fidelity than DNA replication.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Transcription (biology): Enhancers, transcription factors, Mediator complex, and DNA loops in mammalian transcription', 'Setting up for transcription in mammals is regulated by many cis-regulatory elements, including core promoter and promoter-proximal elements that are located near the transcription start sites of genes. Core promoters combined with general transcription factors are sufficient to direct transcription initiation, but generally have low basal activity. Other important cis-regulatory modules are localized in DNA regions that are distant from the transcription start sites. These include enhancers, silencers, insulators and tethering elements. Among this constellation of elements, enhancers and their associated transcription factors have a leading role in the initiation of gene transcription. An enhancer localized in a DNA region distant from the promoter of a gene can have a very large effect on gene transcription, with some genes undergoing up to 100-fold increased transcription due to an activated enhancer.', 'Wikipedia: Transcription (biology)', 'https://en.wikipedia.org/w/index.php?title=Transcription_(biology)&oldid=1376993847', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Setting up for transcription in mammals is regulated by many cis-regulatory elements, including core promoter and promoter-proximal elements that are located near the transcription start sites of genes. Core promoters combined with general transcription factors are sufficient to direct transcription initiation, but generally have low basal activity. Other important cis-regulatory modules are localized in DNA regions that are distant from the transcription start sites. These include enhancers, silencers, insulators and tethering elements. Among this constellation of elements, enhancers and their associated transcription factors have a leading role in the initiation of gene transcription. An enhancer localized in a DNA region distant from the promoter of a gene can have a very large effect on gene transcription, with some genes undergoing up to 100-fold increased transcription due to an activated enhancer.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Transcription (biology): Enhancers, transcription factors, Mediator complex, and DNA loops in mammalian transcription', 'Enhancers are regions of the genome that are major gene-regulatory elements. Enhancers control cell-type-specific gene transcription programs, most often by looping through long distances to come in physical proximity with the promoters of their target genes. While there are hundreds of thousands of enhancer DNA regions, for a particular type of tissue only specific enhancers are brought into proximity with the promoters that they regulate. In a study of brain cortical neurons, 24,937 loops were found, bringing enhancers to their target promoters. Multiple enhancers, each often at tens or hundred of thousands of nucleotides distant from their target genes, loop to their target gene promoters and can coordinate with each other to control transcription of their common target gene.', 'Wikipedia: Transcription (biology)', 'https://en.wikipedia.org/w/index.php?title=Transcription_(biology)&oldid=1376993847', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Enhancers are regions of the genome that are major gene-regulatory elements. Enhancers control cell-type-specific gene transcription programs, most often by looping through long distances to come in physical proximity with the promoters of their target genes. While there are hundreds of thousands of enhancer DNA regions, for a particular type of tissue only specific enhancers are brought into proximity with the promoters that they regulate. In a study of brain cortical neurons, 24,937 loops were found, bringing enhancers to their target promoters. Multiple enhancers, each often at tens or hundred of thousands of nucleotides distant from their target genes, loop to their target gene promoters and can coordinate with each other to control transcription of their common target gene.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Transcription (biology): Enhancers, transcription factors, Mediator complex, and DNA loops in mammalian transcription', 'The schematic illustration in this section shows an enhancer looping around to come into close physical proximity with the promoter of a target gene. The loop is stabilized by a dimer of a connector protein (e.g. dimer of CTCF or YY1), with one member of the dimer anchored to its binding motif on the enhancer and the other member anchored to its binding motif on the promoter (represented by the red zigzags in the illustration). Several cell function specific transcription factors (there are about 1,600 transcription factors in a human cell) generally bind to specific motifs on an enhancer and a small combination of these enhancer-bound transcription factors, when brought close to a promoter by a DNA loop, govern level of transcription of the target gene. Mediator (a complex usually consisting of about 26 proteins in an interacting structure) communicates regulatory signals from enhancer DNA-bound transcription factors directly to the RNA polymerase II (pol II) enzyme bound to the promoter.', 'Wikipedia: Transcription (biology)', 'https://en.wikipedia.org/w/index.php?title=Transcription_(biology)&oldid=1376993847', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The schematic illustration in this section shows an enhancer looping around to come into close physical proximity with the promoter of a target gene. The loop is stabilized by a dimer of a connector protein (e.g. dimer of CTCF or YY1), with one member of the dimer anchored to its binding motif on the enhancer and the other member anchored to its binding motif on the promoter (represented by the red zigzags in the illustration). Several cell function specific transcription factors (there are about 1,600 transcription factors in a human cell) generally bind to specific motifs on an enhancer and a small combination of these enhancer-bound transcription factors, when brought close to a promoter by a DNA loop, govern level of transcription of the target gene. Mediator (a complex usually consisting of about 26 proteins in an interacting structure) communicates regulatory signals from enhancer DNA-bound transcription factors directly to the RNA polymerase II (pol II) enzyme bound to the promoter.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Transcription (biology): Enhancers, transcription factors, Mediator complex, and DNA loops in mammalian transcription', 'Enhancers, when active, are generally transcribed from both strands of DNA with RNA polymerases acting in two different directions, producing two enhancer RNAs (eRNAs) as illustrated in the Figure. An inactive enhancer may be bound by an inactive transcription factor. Phosphorylation of the transcription factor may activate it and that activated transcription factor may then activate the enhancer to which it is bound (see small red star representing phosphorylation of transcription factor bound to enhancer in the illustration). An activated enhancer begins transcription of its RNA before activating transcription of messenger RNA from its target gene.', 'Wikipedia: Transcription (biology)', 'https://en.wikipedia.org/w/index.php?title=Transcription_(biology)&oldid=1376993847', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Enhancers, when active, are generally transcribed from both strands of DNA with RNA polymerases acting in two different directions, producing two enhancer RNAs (eRNAs) as illustrated in the Figure. An inactive enhancer may be bound by an inactive transcription factor. Phosphorylation of the transcription factor may activate it and that activated transcription factor may then activate the enhancer to which it is bound (see small red star representing phosphorylation of transcription factor bound to enhancer in the illustration). An activated enhancer begins transcription of its RNA before activating transcription of messenger RNA from its target gene.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Transcription (biology): CpG island methylation and demethylation', 'Transcription regulation at about 60% of promoters is also controlled by methylation of cytosines within CpG dinucleotides (where 5'' cytosine is followed by 3'' guanine or CpG sites). 5-methylcytosine (5-mC) is a methylated form of the DNA base cytosine (see Figure). 5-mC is an epigenetic marker found predominantly within CpG sites. About 28 million CpG dinucleotides occur in the human genome. In most tissues of mammals, on average, 70% to 80% of CpG cytosines are methylated (forming 5-methylCpG or 5-mCpG). However, unmethylated cytosines within 5''cytosine-guanine 3'' sequences often occur in groups, called CpG islands, at active promoters. About 60% of promoter sequences have a CpG island while only about 6% of enhancer sequences have a CpG island. CpG islands constitute regulatory sequences, since if CpG islands are methylated in the promoter of a gene this can reduce or silence gene transcription.', 'Wikipedia: Transcription (biology)', 'https://en.wikipedia.org/w/index.php?title=Transcription_(biology)&oldid=1376993847', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Transcription regulation at about 60% of promoters is also controlled by methylation of cytosines within CpG dinucleotides (where 5'' cytosine is followed by 3'' guanine or CpG sites). 5-methylcytosine (5-mC) is a methylated form of the DNA base cytosine (see Figure). 5-mC is an epigenetic marker found predominantly within CpG sites. About 28 million CpG dinucleotides occur in the human genome. In most tissues of mammals, on average, 70% to 80% of CpG cytosines are methylated (forming 5-methylCpG or 5-mCpG). However, unmethylated cytosines within 5''cytosine-guanine 3'' sequences often occur in groups, called CpG islands, at active promoters. About 60% of promoter sequences have a CpG island while only about 6% of enhancer sequences have a CpG island. CpG islands constitute regulatory sequences, since if CpG islands are methylated in the promoter of a gene this can reduce or silence gene transcription.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Translation (biology)', 'Translation is the process in biological cells in which proteins are produced using RNA molecules as templates. The generated protein is a sequence of amino acids determined by the sequence of nucleotides in the RNA. The nucleotides are considered three at a time. Each such triple results in the addition of one specific amino acid to the protein being generated. The matching from nucleotide triple to amino acid is called the genetic code. The translation is performed by a large complex of functional RNA and proteins called ribosomes. The entire process is called gene expression. In translation, messenger RNA (mRNA) is decoded in a ribosome, outside the nucleus, to produce a specific amino acid chain, or polypeptide. The polypeptide later folds into an active protein and performs its functions in the cell. The polypeptide can also start folding during protein synthesis. The ribosome facilitates decoding by inducing the binding of complementary transfer RNA (TRNA) anticodon sequences to mRNA codons. The TRNAs carry specific amino acids that are chained together into a polypeptide as the mRNA passes through and is "read" by the ribosome. The three stages of translation are initiation, elongation, and termination.', 'Wikipedia: Translation (biology)', 'https://en.wikipedia.org/w/index.php?title=Translation_(biology)&oldid=1377556947', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Translation is the process in biological cells in which proteins are produced using RNA molecules as templates. The generated protein is a sequence of amino acids determined by the sequence of nucleotides in the RNA. The nucleotides are considered three at a time. Each such triple results in the addition of one specific amino acid to the protein being generated. The matching from nucleotide triple to amino acid is called the genetic code. The translation is performed by a large complex of functional RNA and proteins called ribosomes. The entire process is called gene expression. In translation, messenger RNA (mRNA) is decoded in a ribosome, outside the nucleus, to produce a specific amino acid chain, or polypeptide. The polypeptide later folds into an active protein and performs its functions in the cell. The polypeptide can also start folding during protein synthesis. The ribosome facilitates decoding by inducing the binding of complementary transfer RNA (TRNA) anticodon sequences to mRNA codons. The TRNAs carry specific amino acids that are chained together into a polypeptide as the mRNA passes through and is "read" by the ribosome. The three stages of translation are initiation, elongation, and termination.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Translation (biology): Basic mechanisms', 'The basic process of protein production is the addition of one amino acid at a time to the end of a forming polypeptide chain. This operation is performed by a ribosome. A ribosome is made up of two subunits, in the eukaryote a small (40S) subunit, and a large (60S) subunit. These subunits come together before the translation of mRNA into a protein to provide a location for translation to be carried out and a polypeptide to be produced. The choice of amino acid type to add is determined by a messenger RNA (mRNA) molecule. Each amino acid added is matched to a three-nucleotide subsequence of the mRNA. For each such triplet possible, the corresponding amino acid is accepted. The successive amino acids added to the chain are matched to successive nucleotide triplets in the mRNA. In this way, the sequence of nucleotides in the template mRNA chain determines the sequence of amino acids in the generated amino acid chain. The addition of an amino acid occurs at the C-terminus of the peptide; thus, translation is said to be amine-to-carboxyl directed.', 'Wikipedia: Translation (biology)', 'https://en.wikipedia.org/w/index.php?title=Translation_(biology)&oldid=1377556947', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The basic process of protein production is the addition of one amino acid at a time to the end of a forming polypeptide chain. This operation is performed by a ribosome. A ribosome is made up of two subunits, in the eukaryote a small (40S) subunit, and a large (60S) subunit. These subunits come together before the translation of mRNA into a protein to provide a location for translation to be carried out and a polypeptide to be produced. The choice of amino acid type to add is determined by a messenger RNA (mRNA) molecule. Each amino acid added is matched to a three-nucleotide subsequence of the mRNA. For each such triplet possible, the corresponding amino acid is accepted. The successive amino acids added to the chain are matched to successive nucleotide triplets in the mRNA. In this way, the sequence of nucleotides in the template mRNA chain determines the sequence of amino acids in the generated amino acid chain. The addition of an amino acid occurs at the C-terminus of the peptide; thus, translation is said to be amine-to-carboxyl directed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Translation (biology): Basic mechanisms', 'The mRNA carries genetic information encoded as a ribonucleotide sequence from the chromosomes to the ribosomes. The ribonucleotides are "read" by translational machinery in a sequence of nucleotide triplets called codons. Each of those triplets codes for a specific amino acid. The ribosome molecules translate this code to a specific sequence of amino acids. The ribosome is a multi subunit structure containing ribosomal RNA (TRNA) and proteins. It is the "factory" where amino acids are assembled into proteins. Transfer RNAs (TRNAs) are small noncoding RNA chains (74–93 nucleotides) that transport amino acids to the ribosome. The repertoire of TRNA genes varies widely between species, with some bacteria having between 20 and 30 genes while complex eukaryotes could have thousands. TRNAs have a site for amino acid attachment, and a site called an anticodon. The anticodon is an RNA triplet complementary to the mRNA triplet that codes for their cargo amino acid.', 'Wikipedia: Translation (biology)', 'https://en.wikipedia.org/w/index.php?title=Translation_(biology)&oldid=1377556947', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The mRNA carries genetic information encoded as a ribonucleotide sequence from the chromosomes to the ribosomes. The ribonucleotides are "read" by translational machinery in a sequence of nucleotide triplets called codons. Each of those triplets codes for a specific amino acid. The ribosome molecules translate this code to a specific sequence of amino acids. The ribosome is a multi subunit structure containing ribosomal RNA (TRNA) and proteins. It is the "factory" where amino acids are assembled into proteins. Transfer RNAs (TRNAs) are small noncoding RNA chains (74–93 nucleotides) that transport amino acids to the ribosome. The repertoire of TRNA genes varies widely between species, with some bacteria having between 20 and 30 genes while complex eukaryotes could have thousands. TRNAs have a site for amino acid attachment, and a site called an anticodon. The anticodon is an RNA triplet complementary to the mRNA triplet that codes for their cargo amino acid.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Translation (biology): Basic mechanisms', 'Aminoacyl TRNA synthetases (enzymes) catalyze the bonding between specific TRNAs and the amino acids that their anticodon sequences call for. The product of this reaction is an aminoacyl-TRNA. The amino acid is joined by its carboxyl group to the 3'' OH of the TRNA by an ester bond. When the TRNA has an amino acid linked to it, the TRNA is termed "charged". Aminoacyl-TRNA synthetases that mispair TRNAs with the wrong amino acids can produce mischarged aminoacyl-TRNAs, which can result in inappropriate amino acids at the respective position in the protein. This "mistranslation" of the genetic code naturally occurs at low levels in most organisms, but certain cellular environments cause an increase in permissive mRNA decoding, sometimes to the benefit of the cell.', 'Wikipedia: Translation (biology)', 'https://en.wikipedia.org/w/index.php?title=Translation_(biology)&oldid=1377556947', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Aminoacyl TRNA synthetases (enzymes) catalyze the bonding between specific TRNAs and the amino acids that their anticodon sequences call for. The product of this reaction is an aminoacyl-TRNA. The amino acid is joined by its carboxyl group to the 3'' OH of the TRNA by an ester bond. When the TRNA has an amino acid linked to it, the TRNA is termed "charged". Aminoacyl-TRNA synthetases that mispair TRNAs with the wrong amino acids can produce mischarged aminoacyl-TRNAs, which can result in inappropriate amino acids at the respective position in the protein. This "mistranslation" of the genetic code naturally occurs at low levels in most organisms, but certain cellular environments cause an increase in permissive mRNA decoding, sometimes to the benefit of the cell.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Translation (biology): Basic mechanisms', 'The ribosome has two binding sites for TRNA. They are the aminoacyl site (abbreviated A), and the peptidyl site/ exit site (abbreviated P/E). Concerning the mRNA, the three sites are oriented 5'' to 3'' E-P-A, because ribosomes move toward the 3'' end of mRNA. The A-site binds the incoming TRNA with the complementary codon on the mRNA. The P/E-site holds the TRNA with the growing polypeptide chain. When an aminoacyl-TRNA initially binds to its corresponding codon on the mRNA, it is in the A site. Then, a peptide bond forms between the amino acid of the TRNA in the A site and the amino acid of the charged TRNA in the P/E site. The growing polypeptide chain is transferred to the TRNA in the A site. Translocation occurs, moving the TRNA to the P/E site, now without an amino acid; the TRNA that was in the A site, now charged with the polypeptide chain, is moved to the P/E site and the uncharged TRNA leaves, and another aminoacyl-TRNA enters the A site to repeat the process.', 'Wikipedia: Translation (biology)', 'https://en.wikipedia.org/w/index.php?title=Translation_(biology)&oldid=1377556947', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The ribosome has two binding sites for TRNA. They are the aminoacyl site (abbreviated A), and the peptidyl site/ exit site (abbreviated P/E). Concerning the mRNA, the three sites are oriented 5'' to 3'' E-P-A, because ribosomes move toward the 3'' end of mRNA. The A-site binds the incoming TRNA with the complementary codon on the mRNA. The P/E-site holds the TRNA with the growing polypeptide chain. When an aminoacyl-TRNA initially binds to its corresponding codon on the mRNA, it is in the A site. Then, a peptide bond forms between the amino acid of the TRNA in the A site and the amino acid of the charged TRNA in the P/E site. The growing polypeptide chain is transferred to the TRNA in the A site. Translocation occurs, moving the TRNA to the P/E site, now without an amino acid; the TRNA that was in the A site, now charged with the polypeptide chain, is moved to the P/E site and the uncharged TRNA leaves, and another aminoacyl-TRNA enters the A site to repeat the process.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Translation (biology): Basic mechanisms', 'After the new amino acid is added to the chain, and after the TRNA is released out of the ribosome and into the cytosol, the energy provided by the hydrolysis of a GTP bound to the translocase EEF2 moves the ribosome down one codon towards the 3'' end. The energy required for translation of proteins is significant. For a protein containing n amino acids, the number of high-energy phosphate bonds required to translate it is 4n-1. The rate of translation varies; it is significantly higher in prokaryotic cells (up to 17–21 amino acid residues per second) than in eukaryotic cells (up to 6–9 amino acid residues per second).', 'Wikipedia: Translation (biology)', 'https://en.wikipedia.org/w/index.php?title=Translation_(biology)&oldid=1377556947', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'After the new amino acid is added to the chain, and after the TRNA is released out of the ribosome and into the cytosol, the energy provided by the hydrolysis of a GTP bound to the translocase EEF2 moves the ribosome down one codon towards the 3'' end. The energy required for translation of proteins is significant. For a protein containing n amino acids, the number of high-energy phosphate bonds required to translate it is 4n-1. The rate of translation varies; it is significantly higher in prokaryotic cells (up to 17–21 amino acid residues per second) than in eukaryotic cells (up to 6–9 amino acid residues per second).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Translation (biology): Initiation', 'Initiation involves the small subunit of the ribosome binding to the 5'' end of mRNA with the help of initiation factors. The ribosome and its associated factors assemble and bind to an mRNA. The first TRNA is attached at the start codon. This process is defined as either cap-dependent, in which the ribosome binds initially at the 5'' cap and then travels to the stop codon, or as cap-independent, where the ribosome does not initially bind the 5'' cap. The 5'' cap is added when the nascent pre-mRNA is about 20 nucleotides long.', 'Wikipedia: Translation (biology)', 'https://en.wikipedia.org/w/index.php?title=Translation_(biology)&oldid=1377556947', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Initiation involves the small subunit of the ribosome binding to the 5'' end of mRNA with the help of initiation factors. The ribosome and its associated factors assemble and bind to an mRNA. The first TRNA is attached at the start codon. This process is defined as either cap-dependent, in which the ribosome binds initially at the 5'' cap and then travels to the stop codon, or as cap-independent, where the ribosome does not initially bind the 5'' cap. The 5'' cap is added when the nascent pre-mRNA is about 20 nucleotides long.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Translation (biology): Cap-dependent initiation', 'Initiation of translation usually involves the interaction of certain key proteins, the initiation factors, with a special tag bound to the 5''-end of an mRNA molecule, the 5'' cap, as well as with the 5'' UTR. These proteins bind the small (40S) ribosomal subunit and hold the mRNA in place.', 'Wikipedia: Translation (biology)', 'https://en.wikipedia.org/w/index.php?title=Translation_(biology)&oldid=1377556947', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Initiation of translation usually involves the interaction of certain key proteins, the initiation factors, with a special tag bound to the 5''-end of an mRNA molecule, the 5'' cap, as well as with the 5'' UTR. These proteins bind the small (40S) ribosomal subunit and hold the mRNA in place.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Regulation of gene expression', 'Regulation of gene expression, or gene regulation, includes a wide range of mechanisms that are used by cells to increase or decrease the production of specific gene products (protein or RNA). Sophisticated programs of gene expression are widely observed in biology, for example to trigger developmental pathways, respond to environmental stimuli, or adapt to new food sources. Virtually any step of gene expression can be modulated, from transcriptional initiation, to RNA processing, and to the post-translational modification of a protein. Often, one gene regulator controls another, and so on, in a gene regulatory network. Gene regulation is essential for viruses, prokaryotes and eukaryotes as it increases the versatility and adaptability of an organism by allowing the cell to express protein when needed. Although as early as 1951, Barbara McClintock showed interaction between two genetic loci, Activator (Ac) and Dissociator (Ds), in the color formation of maize seeds, the first discovery of a gene regulation system is widely considered to be the identification in 1961 of the lac operon, discovered by François Jacob and Jacques Monod, in which some enzymes involved in lactose metabolism are expressed by E. coli only in the presence of lactose and absence of glucose.', 'Wikipedia: Regulation of gene expression', 'https://en.wikipedia.org/w/index.php?title=Regulation_of_gene_expression&oldid=1378184072', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Regulation of gene expression, or gene regulation, includes a wide range of mechanisms that are used by cells to increase or decrease the production of specific gene products (protein or RNA). Sophisticated programs of gene expression are widely observed in biology, for example to trigger developmental pathways, respond to environmental stimuli, or adapt to new food sources. Virtually any step of gene expression can be modulated, from transcriptional initiation, to RNA processing, and to the post-translational modification of a protein. Often, one gene regulator controls another, and so on, in a gene regulatory network. Gene regulation is essential for viruses, prokaryotes and eukaryotes as it increases the versatility and adaptability of an organism by allowing the cell to express protein when needed. Although as early as 1951, Barbara McClintock showed interaction between two genetic loci, Activator (Ac) and Dissociator (Ds), in the color formation of maize seeds, the first discovery of a gene regulation system is widely considered to be the identification in 1961 of the lac operon, discovered by François Jacob and Jacques Monod, in which some enzymes involved in lactose metabolism are expressed by E. coli only in the presence of lactose and absence of glucose.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Regulation of gene expression', 'In multicellular organisms, gene regulation drives cellular differentiation and morphogenesis in the embryo, leading to the creation of different cell types that possess different gene expression profiles from the same genome sequence. Although this does not explain how gene regulation originated, evolutionary biologists include it as a partial explanation of how evolution works at a molecular level, and it is central to the science of evolutionary developmental biology ("evo-devo").', 'Wikipedia: Regulation of gene expression', 'https://en.wikipedia.org/w/index.php?title=Regulation_of_gene_expression&oldid=1378184072', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'In multicellular organisms, gene regulation drives cellular differentiation and morphogenesis in the embryo, leading to the creation of different cell types that possess different gene expression profiles from the same genome sequence. Although this does not explain how gene regulation originated, evolutionary biologists include it as a partial explanation of how evolution works at a molecular level, and it is central to the science of evolutionary developmental biology ("evo-devo").');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Regulation of gene expression: Regulated stages of gene expression', 'Any step of gene expression may be modulated, from signaling to transcription to post-translational modification of a protein. The following is a list of stages where gene expression is regulated, where the most extensively utilized point is transcription initiation, the first stage in transcription:', 'Wikipedia: Regulation of gene expression', 'https://en.wikipedia.org/w/index.php?title=Regulation_of_gene_expression&oldid=1378184072', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Any step of gene expression may be modulated, from signaling to transcription to post-translational modification of a protein. The following is a list of stages where gene expression is regulated, where the most extensively utilized point is transcription initiation, the first stage in transcription:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Regulation of gene expression: Modification of DNA', 'In eukaryotes, the accessibility of large regions of DNA can depend on its chromatin structure, which can be altered as a result of histone modifications directed by DNA methylation, ncRNA, or DNA-binding protein. Hence these modifications may up or down regulate the expression of a gene. Some of these modifications that regulate gene expression are inheritable and are referred to as epigenetic regulation.', 'Wikipedia: Regulation of gene expression', 'https://en.wikipedia.org/w/index.php?title=Regulation_of_gene_expression&oldid=1378184072', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'In eukaryotes, the accessibility of large regions of DNA can depend on its chromatin structure, which can be altered as a result of histone modifications directed by DNA methylation, ncRNA, or DNA-binding protein. Hence these modifications may up or down regulate the expression of a gene. Some of these modifications that regulate gene expression are inheritable and are referred to as epigenetic regulation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Regulation of gene expression: Structural', 'Transcription of DNA is dictated by its structure. In general, the density of its packing is indicative of the frequency of transcription. Octameric protein complexes called histones together with a segment of DNA wound around the eight histone proteins (together referred to as a nucleosome) are responsible for the amount of supercoiling of DNA, and these complexes can be temporarily modified by processes such as phosphorylation or more permanently modified by processes such as methylation. Such modifications are considered to be responsible for more or less permanent changes in gene expression levels.', 'Wikipedia: Regulation of gene expression', 'https://en.wikipedia.org/w/index.php?title=Regulation_of_gene_expression&oldid=1378184072', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Transcription of DNA is dictated by its structure. In general, the density of its packing is indicative of the frequency of transcription. Octameric protein complexes called histones together with a segment of DNA wound around the eight histone proteins (together referred to as a nucleosome) are responsible for the amount of supercoiling of DNA, and these complexes can be temporarily modified by processes such as phosphorylation or more permanently modified by processes such as methylation. Such modifications are considered to be responsible for more or less permanent changes in gene expression levels.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Regulation of gene expression: Chemical', 'Methylation of DNA is a common method of gene silencing. DNA is typically methylated by methyltransferase enzymes on cytosine nucleotides in a CpG dinucleotide sequence (also called "CpG islands" when densely clustered). Analysis of the pattern of methylation in a given region of DNA (which can be a promoter) can be achieved through a method called bisulfite mapping. Methylated cytosine residues are unchanged by the treatment, whereas unmethylated ones are changed to uracil. The differences are analyzed by DNA sequencing or by methods developed to quantify SNPs, such as Pyrosequencing (Biotage) or MassArray (Sequenom), measuring the relative amounts of C/T at the CG dinucleotide. Abnormal methylation patterns are thought to be involved in oncogenesis. Histone acetylation is also an important process in transcription. Histone acetyltransferase enzymes (HATs) such as CREB-binding protein also dissociate the DNA from the histone complex, allowing transcription to proceed. Often, DNA methylation and histone deacetylation work together in gene silencing. The combination of the two seems to be a signal for DNA to be packed more densely, lowering gene expression.', 'Wikipedia: Regulation of gene expression', 'https://en.wikipedia.org/w/index.php?title=Regulation_of_gene_expression&oldid=1378184072', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Methylation of DNA is a common method of gene silencing. DNA is typically methylated by methyltransferase enzymes on cytosine nucleotides in a CpG dinucleotide sequence (also called "CpG islands" when densely clustered). Analysis of the pattern of methylation in a given region of DNA (which can be a promoter) can be achieved through a method called bisulfite mapping. Methylated cytosine residues are unchanged by the treatment, whereas unmethylated ones are changed to uracil. The differences are analyzed by DNA sequencing or by methods developed to quantify SNPs, such as Pyrosequencing (Biotage) or MassArray (Sequenom), measuring the relative amounts of C/T at the CG dinucleotide. Abnormal methylation patterns are thought to be involved in oncogenesis. Histone acetylation is also an important process in transcription. Histone acetyltransferase enzymes (HATs) such as CREB-binding protein also dissociate the DNA from the histone complex, allowing transcription to proceed. Often, DNA methylation and histone deacetylation work together in gene silencing. The combination of the two seems to be a signal for DNA to be packed more densely, lowering gene expression.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Regulation of gene expression: Regulation of transcription', 'Regulation of transcription thus controls when transcription occurs and how much RNA is created. Transcription of a gene by RNA polymerase can be regulated by several mechanisms. Specificity factors alter the specificity of RNA polymerase for a given promoter or set of promoters, making it more or less likely to bind to them (i.e., sigma factors used in prokaryotic transcription). Repressors bind to the Operator, coding sequences on the DNA strand that are close to or overlapping the promoter region, impeding RNA polymerase''s progress along the strand, thus impeding the expression of the gene. The image to the right demonstrates regulation by a repressor in the lac operon. General transcription factors position RNA polymerase at the start of a protein-coding sequence and then release the polymerase to transcribe the mRNA. Activators enhance the interaction between RNA polymerase and a particular promoter, encouraging the expression of the gene. Activators do this by increasing the attraction of RNA polymerase for the promoter, through interactions with subunits of the RNA polymerase or indirectly by changing the structure of the DNA. Enhancers are sites on the DNA helix that are bound by activators in order to loop the DNA bringing a specific promoter to the initiation complex. Enhancers are much more common in eukaryotes than prokaryotes, where only a few examples exist (to date).', 'Wikipedia: Regulation of gene expression', 'https://en.wikipedia.org/w/index.php?title=Regulation_of_gene_expression&oldid=1378184072', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Regulation of transcription thus controls when transcription occurs and how much RNA is created. Transcription of a gene by RNA polymerase can be regulated by several mechanisms. Specificity factors alter the specificity of RNA polymerase for a given promoter or set of promoters, making it more or less likely to bind to them (i.e., sigma factors used in prokaryotic transcription). Repressors bind to the Operator, coding sequences on the DNA strand that are close to or overlapping the promoter region, impeding RNA polymerase''s progress along the strand, thus impeding the expression of the gene. The image to the right demonstrates regulation by a repressor in the lac operon. General transcription factors position RNA polymerase at the start of a protein-coding sequence and then release the polymerase to transcribe the mRNA. Activators enhance the interaction between RNA polymerase and a particular promoter, encouraging the expression of the gene. Activators do this by increasing the attraction of RNA polymerase for the promoter, through interactions with subunits of the RNA polymerase or indirectly by changing the structure of the DNA. Enhancers are sites on the DNA helix that are bound by activators in order to loop the DNA bringing a specific promoter to the initiation complex. Enhancers are much more common in eukaryotes than prokaryotes, where only a few examples exist (to date).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Regulation of gene expression: Regulation of transcription', 'Silencers are regions of DNA sequences that, when bound by particular transcription factors, can silence expression of the gene.', 'Wikipedia: Regulation of gene expression', 'https://en.wikipedia.org/w/index.php?title=Regulation_of_gene_expression&oldid=1378184072', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Silencers are regions of DNA sequences that, when bound by particular transcription factors, can silence expression of the gene.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Lac operon', 'The lactose operon (lac operon) is an operon required for the transport and metabolism of lactose in E. coli and many other enteric bacteria. Although glucose is the preferred carbon source for most enteric bacteria, the lac operon allows for the effective digestion of lactose when glucose is not available through the activity of β-galactosidase. Gene regulation of the lac operon was the first genetic regulatory mechanism to be understood clearly, so it has become a foremost example of prokaryotic gene regulation. It is often discussed in introductory molecular and cellular biology classes for this reason. This lactose metabolism system was used by François Jacob and Jacques Monod to determine how a biological cell knows which enzyme to synthesize. Their work on the lac operon won them the Nobel Prize in Physiology in 1965. Most bacterial cells including E. coli lack introns in their genome. They also lack a nuclear membrane. Hence the gene regulation by lac operon occurs at the transcriptional level, by controlling transcription of DNA.', 'Wikipedia: Lac operon', 'https://en.wikipedia.org/w/index.php?title=Lac_operon&oldid=1362920271', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The lactose operon (lac operon) is an operon required for the transport and metabolism of lactose in E. coli and many other enteric bacteria. Although glucose is the preferred carbon source for most enteric bacteria, the lac operon allows for the effective digestion of lactose when glucose is not available through the activity of β-galactosidase. Gene regulation of the lac operon was the first genetic regulatory mechanism to be understood clearly, so it has become a foremost example of prokaryotic gene regulation. It is often discussed in introductory molecular and cellular biology classes for this reason. This lactose metabolism system was used by François Jacob and Jacques Monod to determine how a biological cell knows which enzyme to synthesize. Their work on the lac operon won them the Nobel Prize in Physiology in 1965. Most bacterial cells including E. coli lack introns in their genome. They also lack a nuclear membrane. Hence the gene regulation by lac operon occurs at the transcriptional level, by controlling transcription of DNA.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Lac operon', 'Bacterial operons are polycistronic transcripts that are able to produce multiple proteins from one mRNA transcript. In this case, when lactose is required as a sugar source for the bacterium, the three genes of the lac operon can be transcribed and their subsequent proteins translated: lacZ, lacY, and lacA. The gene product of lacZ is β-galactosidase which cleaves lactose, a disaccharide, into glucose and galactose. lacY encodes β-galactoside permease, a membrane protein which becomes embedded in the Plasma membrane to enable the cellular transport of lactose into the cell. Finally, lacA encodes β-galactoside transacetylase. Note that the number of base pairs in diagram given above are not to scale. There are in fact over 5300 base pairs in the lac operon. It would be wasteful to produce enzymes when no lactose is available or if a preferable energy source such as glucose were available. The lac operon uses a two-part control mechanism to ensure that the cell expends energy producing the enzymes encoded by the lac operon only when necessary.', 'Wikipedia: Lac operon', 'https://en.wikipedia.org/w/index.php?title=Lac_operon&oldid=1362920271', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Bacterial operons are polycistronic transcripts that are able to produce multiple proteins from one mRNA transcript. In this case, when lactose is required as a sugar source for the bacterium, the three genes of the lac operon can be transcribed and their subsequent proteins translated: lacZ, lacY, and lacA. The gene product of lacZ is β-galactosidase which cleaves lactose, a disaccharide, into glucose and galactose. lacY encodes β-galactoside permease, a membrane protein which becomes embedded in the Plasma membrane to enable the cellular transport of lactose into the cell. Finally, lacA encodes β-galactoside transacetylase. Note that the number of base pairs in diagram given above are not to scale. There are in fact over 5300 base pairs in the lac operon. It would be wasteful to produce enzymes when no lactose is available or if a preferable energy source such as glucose were available. The lac operon uses a two-part control mechanism to ensure that the cell expends energy producing the enzymes encoded by the lac operon only when necessary.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Lac operon', 'In the absence of lactose, the lac repressor, encoded by lacI, halts production of the enzymes and transport proteins encoded by the lac operon. It does so by blocking the DNA dependent RNA polymerase. This blocking/ halting is not perfect, and a minimal amount of gene expression does take place all the time. The repressor protein is always expressed, but the lac operon (i.e. enzymes and transport proteins) are almost completely repressed, allowing for a small level of background expression. If this weren''t the case, there would be no lacY transporter protein in the cellular membrane; consequently, the lac operon would not be able to detect the presence of lactose. When lactose is available but not glucose, then some lactose enters the cell using pre-existing transport protein encoded by lacY. This lactose then combines with the repressor and inactivates it, hence allowing the lac operon to be expressed. Then more β-galactoside permease is synthesized allowing even more lactose to enter and the enzymes encoded by lacZ and lacA can digest it.', 'Wikipedia: Lac operon', 'https://en.wikipedia.org/w/index.php?title=Lac_operon&oldid=1362920271', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'In the absence of lactose, the lac repressor, encoded by lacI, halts production of the enzymes and transport proteins encoded by the lac operon. It does so by blocking the DNA dependent RNA polymerase. This blocking/ halting is not perfect, and a minimal amount of gene expression does take place all the time. The repressor protein is always expressed, but the lac operon (i.e. enzymes and transport proteins) are almost completely repressed, allowing for a small level of background expression. If this weren''t the case, there would be no lacY transporter protein in the cellular membrane; consequently, the lac operon would not be able to detect the presence of lactose. When lactose is available but not glucose, then some lactose enters the cell using pre-existing transport protein encoded by lacY. This lactose then combines with the repressor and inactivates it, hence allowing the lac operon to be expressed. Then more β-galactoside permease is synthesized allowing even more lactose to enter and the enzymes encoded by lacZ and lacA can digest it.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Lac operon', 'However, in the presence of glucose, regardless of the presence of lactose, the operon will be repressed. This is because the catabolite activator protein (CAP), required for production of the enzymes, remains inactive, and EIIAGlc shuts down lactose permease to prevent transport of lactose into the cell. This dual control mechanism causes the sequential utilization of glucose and lactose in two distinct growth phases, known as diauxie.', 'Wikipedia: Lac operon', 'https://en.wikipedia.org/w/index.php?title=Lac_operon&oldid=1362920271', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'However, in the presence of glucose, regardless of the presence of lactose, the operon will be repressed. This is because the catabolite activator protein (CAP), required for production of the enzymes, remains inactive, and EIIAGlc shuts down lactose permease to prevent transport of lactose into the cell. This dual control mechanism causes the sequential utilization of glucose and lactose in two distinct growth phases, known as diauxie.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Lac operon: Structure', 'The lac operon consists of 3 structural genes, and a promoter, a terminator, regulator, and an operator. The three structural genes are: lacZ, lacY, and lacA. lacZ encodes β-galactosidase (LacZ), an intracellular enzyme that cleaves the disaccharide lactose into glucose and galactose. It also plays a role in converting lactose into allolactose (which regulates the lac repressor). lacY encodes β-galactoside permease (LacY), a transmembrane symporter that pumps β-galactosides including lactose into the cell using a proton gradient in the same direction. Permease increases the permeability of the cell to β-galactosides. lacA encodes β-galactoside transacetylase (LacA), an enzyme that transfers an acetyl group from acetyl-CoA to thiogalactoside. Only lacZ and lacY appear to be necessary for lactose catabolic pathway. By numbers, lacI has 1100 bps, lacZ has 3000 bps, lacY has 800 bps, lacA has 800 bps, with 3 bps corresponding to 1 amino acid.', 'Wikipedia: Lac operon', 'https://en.wikipedia.org/w/index.php?title=Lac_operon&oldid=1362920271', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The lac operon consists of 3 structural genes, and a promoter, a terminator, regulator, and an operator. The three structural genes are: lacZ, lacY, and lacA. lacZ encodes β-galactosidase (LacZ), an intracellular enzyme that cleaves the disaccharide lactose into glucose and galactose. It also plays a role in converting lactose into allolactose (which regulates the lac repressor). lacY encodes β-galactoside permease (LacY), a transmembrane symporter that pumps β-galactosides including lactose into the cell using a proton gradient in the same direction. Permease increases the permeability of the cell to β-galactosides. lacA encodes β-galactoside transacetylase (LacA), an enzyme that transfers an acetyl group from acetyl-CoA to thiogalactoside. Only lacZ and lacY appear to be necessary for lactose catabolic pathway. By numbers, lacI has 1100 bps, lacZ has 3000 bps, lacY has 800 bps, lacA has 800 bps, with 3 bps corresponding to 1 amino acid.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Lac operon: Genetic nomenclature', 'Three-letter abbreviations are used to describe phenotypes in bacteria including E. coli. In the case of Lac, wild type cells are Lac+ and are able to use lactose as a carbon and energy source, while Lac− mutant derivatives cannot use lactose. The same three letters are typically used (lower-case, italicized) to label the genes involved in a particular phenotype, where each different gene is additionally distinguished by an extra letter. The lac genes encoding enzymes are lacZ, lacY, and lacA. The fourth lac gene is lacI, encoding the lactose repressor—"I" stands for inducibility. One may distinguish between structural genes encoding enzymes, and regulatory genes encoding proteins that affect gene expression. Current usage expands the phenotypic nomenclature to apply to proteins: thus, LacZ is the protein product of the lacZ gene, β-galactosidase. Various short sequences that are not genes also affect gene expression, including the lac promoter, lac p, and the lac operator, lac o. Although it is not strictly standard usage, mutations affecting lac o are referred to as lac oc, for historical reasons.', 'Wikipedia: Lac operon', 'https://en.wikipedia.org/w/index.php?title=Lac_operon&oldid=1362920271', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Three-letter abbreviations are used to describe phenotypes in bacteria including E. coli. In the case of Lac, wild type cells are Lac+ and are able to use lactose as a carbon and energy source, while Lac− mutant derivatives cannot use lactose. The same three letters are typically used (lower-case, italicized) to label the genes involved in a particular phenotype, where each different gene is additionally distinguished by an extra letter. The lac genes encoding enzymes are lacZ, lacY, and lacA. The fourth lac gene is lacI, encoding the lactose repressor—"I" stands for inducibility. One may distinguish between structural genes encoding enzymes, and regulatory genes encoding proteins that affect gene expression. Current usage expands the phenotypic nomenclature to apply to proteins: thus, LacZ is the protein product of the lacZ gene, β-galactosidase. Various short sequences that are not genes also affect gene expression, including the lac promoter, lac p, and the lac operator, lac o. Although it is not strictly standard usage, mutations affecting lac o are referred to as lac oc, for historical reasons.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Lac operon: Regulation', 'Specific control of the lac genes depends on the availability of the substrate lactose to the bacterium. The proteins are not produced by the bacterium when lactose is unavailable as a carbon source.', 'Wikipedia: Lac operon', 'https://en.wikipedia.org/w/index.php?title=Lac_operon&oldid=1362920271', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Specific control of the lac genes depends on the availability of the substrate lactose to the bacterium. The proteins are not produced by the bacterium when lactose is unavailable as a carbon source.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Lac operon: Regulation', 'The lac genes are organized into an operon; that is, they are oriented in the same direction immediately adjacent on the chromosome and are co-transcribed into a single polycistronic mRNA molecule. Transcription of all genes starts with the binding of the enzyme RNA polymerase (RNAP), a DNA-binding protein, which binds to a specific DNA binding site, the promoter, immediately upstream of the genes. Binding of RNA polymerase to the promoter is aided by the cAMP-bound catabolite activator protein (CAP, also known as the cAMP receptor protein). However, the lacI gene (regulatory gene for lac operon) produces a protein that blocks RNAP from binding to the operator of the operon. This protein can only be removed when allolactose binds to it, and inactivates it. The protein that is formed by the lacI gene is known as the lac repressor. The type of regulation that the lac operon undergoes is referred to as negative inducible, meaning that the gene is turned off by the regulatory factor (lac repressor) unless some molecule (lactose) is added. Once the repressor is removed, RNAP then proceeds to transcribe all three genes (lacZYA) into mRNA. Each of the three genes on the mRNA strand has its own Shine-Dalgarno sequence, so the genes are independently translated. The DNA sequence of the E. coli lac operon, the lacZYA mRNA, and the lacI genes are available from GenBank (view).', 'Wikipedia: Lac operon', 'https://en.wikipedia.org/w/index.php?title=Lac_operon&oldid=1362920271', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'The lac genes are organized into an operon; that is, they are oriented in the same direction immediately adjacent on the chromosome and are co-transcribed into a single polycistronic mRNA molecule. Transcription of all genes starts with the binding of the enzyme RNA polymerase (RNAP), a DNA-binding protein, which binds to a specific DNA binding site, the promoter, immediately upstream of the genes. Binding of RNA polymerase to the promoter is aided by the cAMP-bound catabolite activator protein (CAP, also known as the cAMP receptor protein). However, the lacI gene (regulatory gene for lac operon) produces a protein that blocks RNAP from binding to the operator of the operon. This protein can only be removed when allolactose binds to it, and inactivates it. The protein that is formed by the lacI gene is known as the lac repressor. The type of regulation that the lac operon undergoes is referred to as negative inducible, meaning that the gene is turned off by the regulatory factor (lac repressor) unless some molecule (lactose) is added. Once the repressor is removed, RNAP then proceeds to transcribe all three genes (lacZYA) into mRNA. Each of the three genes on the mRNA strand has its own Shine-Dalgarno sequence, so the genes are independently translated. The DNA sequence of the E. coli lac operon, the lacZYA mRNA, and the lacI genes are available from GenBank (view).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Mutation', 'In biology, a mutation is an alteration in the nucleic acid sequence of the genome of an organism, virus, or extrachromosomal DNA. Mutations result from errors during replication, mitosis, meiosis, or damage to DNA, which then may trigger error-prone repair or cause an error during replication (translesion synthesis). Mutations may also result from substitution, insertion or deletion of segments of DNA due to mobile genetic elements. Mutations may or may not produce detectable changes in the observable characteristics (phenotype) of an organism. Mutations play a part in both normal and abnormal biological processes including: evolution, cancer, and the development of the immune system, including junctional diversity. Mutation is the ultimate source of all genetic variation, providing the raw material on which evolutionary forces such as natural selection can act. Mutation can result in many different types of change in sequences. Mutations in genes can have no effect, alter the product of a gene, or prevent the gene from functioning properly or completely. Mutations can also occur in non-genic regions. A 2007 study on genetic variations between different species of Drosophila suggested that, if a mutation changes a protein produced by a gene, the result is likely to be harmful, with an estimated 70% of amino acid polymorphisms having damaging effects, and the remainder being either neutral or marginally beneficial.', 'Wikipedia: Mutation', 'https://en.wikipedia.org/w/index.php?title=Mutation&oldid=1381464888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'In biology, a mutation is an alteration in the nucleic acid sequence of the genome of an organism, virus, or extrachromosomal DNA. Mutations result from errors during replication, mitosis, meiosis, or damage to DNA, which then may trigger error-prone repair or cause an error during replication (translesion synthesis). Mutations may also result from substitution, insertion or deletion of segments of DNA due to mobile genetic elements. Mutations may or may not produce detectable changes in the observable characteristics (phenotype) of an organism. Mutations play a part in both normal and abnormal biological processes including: evolution, cancer, and the development of the immune system, including junctional diversity. Mutation is the ultimate source of all genetic variation, providing the raw material on which evolutionary forces such as natural selection can act. Mutation can result in many different types of change in sequences. Mutations in genes can have no effect, alter the product of a gene, or prevent the gene from functioning properly or completely. Mutations can also occur in non-genic regions. A 2007 study on genetic variations between different species of Drosophila suggested that, if a mutation changes a protein produced by a gene, the result is likely to be harmful, with an estimated 70% of amino acid polymorphisms having damaging effects, and the remainder being either neutral or marginally beneficial.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Mutation', 'Mutation and DNA damage are the two major types of errors that occur in DNA, but they are fundamentally different. DNA damage is a physical alteration in the DNA structure, such as a single or double strand break, a modified guanosine residue in DNA such as 8-hydroxydeoxyguanosine, or a polycyclic aromatic hydrocarbon adduct. DNA damages can be recognized by enzymes, and therefore can be correctly repaired using the complementary undamaged strand in DNA as a template or an undamaged sequence in a homologous chromosome if it is available. If DNA damage remains in a cell, transcription of a gene may be prevented and thus translation into a protein may also be blocked. DNA replication may also be blocked and/or the cell may die. In contrast to a DNA damage, a mutation is an alteration of the base sequence of the DNA. Ordinarily, a mutation cannot be recognized by enzymes once the base change is present in both DNA strands, and thus a mutation is not ordinarily repaired. At the cellular level, mutations can alter protein function and regulation. Unlike DNA damages, mutations are replicated when the cell replicates. At the level of cell populations, cells with mutations will increase or decrease in frequency according to the effects of the mutations on the ability of the cell to survive and reproduce. Although distinctly different from each other, DNA damages and mutations are related because DNA damages often cause errors of DNA synthesis during replication or repair and these errors are a major source of mutation.', 'Wikipedia: Mutation', 'https://en.wikipedia.org/w/index.php?title=Mutation&oldid=1381464888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Mutation and DNA damage are the two major types of errors that occur in DNA, but they are fundamentally different. DNA damage is a physical alteration in the DNA structure, such as a single or double strand break, a modified guanosine residue in DNA such as 8-hydroxydeoxyguanosine, or a polycyclic aromatic hydrocarbon adduct. DNA damages can be recognized by enzymes, and therefore can be correctly repaired using the complementary undamaged strand in DNA as a template or an undamaged sequence in a homologous chromosome if it is available. If DNA damage remains in a cell, transcription of a gene may be prevented and thus translation into a protein may also be blocked. DNA replication may also be blocked and/or the cell may die. In contrast to a DNA damage, a mutation is an alteration of the base sequence of the DNA. Ordinarily, a mutation cannot be recognized by enzymes once the base change is present in both DNA strands, and thus a mutation is not ordinarily repaired. At the cellular level, mutations can alter protein function and regulation. Unlike DNA damages, mutations are replicated when the cell replicates. At the level of cell populations, cells with mutations will increase or decrease in frequency according to the effects of the mutations on the ability of the cell to survive and reproduce. Although distinctly different from each other, DNA damages and mutations are related because DNA damages often cause errors of DNA synthesis during replication or repair and these errors are a major source of mutation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Mutation: Overview', 'Mutations can involve the duplication of large sections of DNA, usually through genetic recombination. These duplications are a major source of raw material for evolving new genes, with tens to hundreds of genes duplicated in animal genomes every million years. Most genes belong to larger gene families of shared ancestry, detectable by their sequence homology. Novel genes are produced by several methods, commonly through the duplication and mutation of an ancestral gene, or by recombining parts of different genes to form new combinations with new functions. Here, protein domains act as modules, each with a particular and independent function, that can be mixed together to produce genes encoding new proteins with novel properties. For example, the human eye uses four genes to make structures that sense light: three for cone cell or colour vision and one for rod cell or night vision; all four arose from a single ancestral gene. Another advantage of duplicating a gene (or even an entire genome) is that this increases engineering redundancy; this allows one gene in the pair to acquire a new function while the other copy performs the original function. Other types of mutation occasionally create new genes from previously noncoding DNA.', 'Wikipedia: Mutation', 'https://en.wikipedia.org/w/index.php?title=Mutation&oldid=1381464888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Mutations can involve the duplication of large sections of DNA, usually through genetic recombination. These duplications are a major source of raw material for evolving new genes, with tens to hundreds of genes duplicated in animal genomes every million years. Most genes belong to larger gene families of shared ancestry, detectable by their sequence homology. Novel genes are produced by several methods, commonly through the duplication and mutation of an ancestral gene, or by recombining parts of different genes to form new combinations with new functions. Here, protein domains act as modules, each with a particular and independent function, that can be mixed together to produce genes encoding new proteins with novel properties. For example, the human eye uses four genes to make structures that sense light: three for cone cell or colour vision and one for rod cell or night vision; all four arose from a single ancestral gene. Another advantage of duplicating a gene (or even an entire genome) is that this increases engineering redundancy; this allows one gene in the pair to acquire a new function while the other copy performs the original function. Other types of mutation occasionally create new genes from previously noncoding DNA.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Mutation: Overview', 'Changes in chromosome number may involve even larger mutations, where segments of the DNA within chromosomes break and then rearrange. For example, in the Homininae, two chromosomes fused to produce human chromosome 2; this fusion did not occur in the lineage of the other apes, and they retain these separate chromosomes. In evolution, the most important role of such chromosomal rearrangements may be to accelerate the divergence of a population into new species by making populations less likely to interbreed, thereby preserving genetic differences between these populations. Sequences of DNA that can move about the genome, such as transposons, make up a major fraction of the genetic material of plants and animals, and may have been important in the evolution of genomes. For example, more than a million copies of the Alu sequence are present in the human genome, and these sequences have now been recruited to perform functions such as regulating gene expression. Another effect of these mobile DNA sequences is that when they move within a genome, they can mutate or delete existing genes and thereby produce genetic diversity.', 'Wikipedia: Mutation', 'https://en.wikipedia.org/w/index.php?title=Mutation&oldid=1381464888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Changes in chromosome number may involve even larger mutations, where segments of the DNA within chromosomes break and then rearrange. For example, in the Homininae, two chromosomes fused to produce human chromosome 2; this fusion did not occur in the lineage of the other apes, and they retain these separate chromosomes. In evolution, the most important role of such chromosomal rearrangements may be to accelerate the divergence of a population into new species by making populations less likely to interbreed, thereby preserving genetic differences between these populations. Sequences of DNA that can move about the genome, such as transposons, make up a major fraction of the genetic material of plants and animals, and may have been important in the evolution of genomes. For example, more than a million copies of the Alu sequence are present in the human genome, and these sequences have now been recruited to perform functions such as regulating gene expression. Another effect of these mobile DNA sequences is that when they move within a genome, they can mutate or delete existing genes and thereby produce genetic diversity.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Mutation: Overview', 'Nonlethal mutations accumulate within the gene pool and increase the amount of genetic variation. The abundance of some genetic changes within the gene pool can be reduced by natural selection, while other "more favorable" mutations may accumulate and result in adaptive changes. For example, a butterfly may produce offspring with new mutations. The majority of these mutations will have no effect; but one might change the colour of one of the butterfly''s offspring, making it harder (or easier) for predators to see. If this color change is advantageous, the chances of this butterfly''s surviving and producing its own offspring are a little better, and over time the number of butterflies with this mutation may form a larger percentage of the population. Neutral mutations are defined as mutations whose effects do not influence the fitness of an individual. These can increase in frequency over time due to genetic drift. It is believed that the overwhelming majority of mutations have no significant effect on an organism''s fitness. Also, DNA repair mechanisms are able to mend most changes before they become permanent mutations, and many organisms have mechanisms, such as apoptotic pathways, for eliminating otherwise-permanently mutated somatic cells.', 'Wikipedia: Mutation', 'https://en.wikipedia.org/w/index.php?title=Mutation&oldid=1381464888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Nonlethal mutations accumulate within the gene pool and increase the amount of genetic variation. The abundance of some genetic changes within the gene pool can be reduced by natural selection, while other "more favorable" mutations may accumulate and result in adaptive changes. For example, a butterfly may produce offspring with new mutations. The majority of these mutations will have no effect; but one might change the colour of one of the butterfly''s offspring, making it harder (or easier) for predators to see. If this color change is advantageous, the chances of this butterfly''s surviving and producing its own offspring are a little better, and over time the number of butterflies with this mutation may form a larger percentage of the population. Neutral mutations are defined as mutations whose effects do not influence the fitness of an individual. These can increase in frequency over time due to genetic drift. It is believed that the overwhelming majority of mutations have no significant effect on an organism''s fitness. Also, DNA repair mechanisms are able to mend most changes before they become permanent mutations, and many organisms have mechanisms, such as apoptotic pathways, for eliminating otherwise-permanently mutated somatic cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Mutation: Causes', 'Four classes of mutations are (1) spontaneous mutations (molecular decay), (2) mutations due to error-prone replication bypass of naturally occurring DNA damage (also called error-prone translesion synthesis), (3) errors introduced during DNA repair, and (4) induced mutations caused by mutagens. Scientists may sometimes deliberately introduce mutations into cells or research organisms for the sake of scientific experimentation. One 2017 study claimed that 66% of cancer-causing mutations are random, 29% are due to the environment (the studied population spanned 69 countries), and 5% are inherited. Humans on average pass 60 new mutations to their children but fathers pass more mutations depending on their age with every year adding two new mutations to a child.', 'Wikipedia: Mutation', 'https://en.wikipedia.org/w/index.php?title=Mutation&oldid=1381464888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Four classes of mutations are (1) spontaneous mutations (molecular decay), (2) mutations due to error-prone replication bypass of naturally occurring DNA damage (also called error-prone translesion synthesis), (3) errors introduced during DNA repair, and (4) induced mutations caused by mutagens. Scientists may sometimes deliberately introduce mutations into cells or research organisms for the sake of scientific experimentation. One 2017 study claimed that 66% of cancer-causing mutations are random, 29% are due to the environment (the studied population spanned 69 countries), and 5% are inherited. Humans on average pass 60 new mutations to their children but fathers pass more mutations depending on their age with every year adding two new mutations to a child.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Mutation: Spontaneous mutation', 'Spontaneous mutations occur with non-zero probability even given a healthy, uncontaminated cell. Naturally occurring oxidative DNA damage is estimated to occur 10,000 times per cell per day in humans and 100,000 times per cell per day in rats. Spontaneous mutations can be characterized by the specific change: Tautomerism – A base is changed by the repositioning of a hydrogen atom, altering the hydrogen bonding pattern of that base, resulting in incorrect base pairing during replication. Theoretical results suggest that proton tunneling is an important factor in the spontaneous creation of GC tautomers. Depurination – Loss of a purine base (A or G) to form an apurinic site (AP site). Deamination – Hydrolysis changes a normal base to an atypical base containing a keto group in place of the original amine group. Examples include C → U and A → HX (hypoxanthine), which can be corrected by DNA repair mechanisms; and 5MeC (5-methylcytosine) → T, which is less likely to be detected as a mutation because thymine is a normal DNA base. Slipped strand mispairing – Denaturation of the new strand from the template during replication, followed by renaturation in a different spot ("slipping"). This can lead to insertions or deletions.', 'Wikipedia: Mutation', 'https://en.wikipedia.org/w/index.php?title=Mutation&oldid=1381464888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'Spontaneous mutations occur with non-zero probability even given a healthy, uncontaminated cell. Naturally occurring oxidative DNA damage is estimated to occur 10,000 times per cell per day in humans and 100,000 times per cell per day in rats. Spontaneous mutations can be characterized by the specific change: Tautomerism – A base is changed by the repositioning of a hydrogen atom, altering the hydrogen bonding pattern of that base, resulting in incorrect base pairing during replication. Theoretical results suggest that proton tunneling is an important factor in the spontaneous creation of GC tautomers. Depurination – Loss of a purine base (A or G) to form an apurinic site (AP site). Deamination – Hydrolysis changes a normal base to an atypical base containing a keto group in place of the original amine group. Examples include C → U and A → HX (hypoxanthine), which can be corrected by DNA repair mechanisms; and 5MeC (5-methylcytosine) → T, which is less likely to be detected as a mutation because thymine is a normal DNA base. Slipped strand mispairing – Denaturation of the new strand from the template during replication, followed by renaturation in a different spot ("slipping"). This can lead to insertions or deletions.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'dna-gene-expression', 'Mutation: Error-prone replication bypass', 'There is increasing evidence that the majority of spontaneously arising mutations are due to error-prone replication (translesion synthesis) past DNA damage in the template strand. In mice, the majority of mutations are caused by translesion synthesis. Likewise, in yeast, Kunz et al. found that more than 60% of the spontaneous single base pair substitutions and deletions were caused by translesion synthesis.', 'Wikipedia: Mutation', 'https://en.wikipedia.org/w/index.php?title=Mutation&oldid=1381464888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'dna-gene-expression' and body = 'There is increasing evidence that the majority of spontaneously arising mutations are due to error-prone replication (translesion synthesis) past DNA damage in the template strand. In mice, the majority of mutations are caused by translesion synthesis. Likewise, in yeast, Kunz et al. found that more than 60% of the spontaneous single base pair substitutions and deletions were caused by translesion synthesis.');
